// ✏️  FILL IN THE VALUES BELOW, then click Save.
// Every other node in this workflow reads its settings from here.
return [{
  json: {
    // Base URL of your calendar's availability API
    calendar_api_url: "https://acuityscheduling.com/api/v1",
    // Sent as: Authorization: Bearer <key>
    calendar_api_key: "PASTE_YOUR_CALENDAR_API_KEY",
  },
}];

const req = $('Vapi Tool Call').first().json;
const body = req.body ?? req;
const msg = body.message ?? body;
const call = msg.call ?? body.call ?? {};
const toolCall =
  (msg.toolCallList ?? msg.toolCalls ?? [])[0] ??
  msg.toolWithToolCallList?.[0]?.toolCall ?? {};
let args = toolCall.function?.arguments ?? toolCall.arguments ?? {};
if (typeof args === 'string') {
  try { args = JSON.parse(args); } catch { args = {}; }
}
const toolCallId = toolCall.id ?? '';

return [{
  json: {
    tool_call_id: toolCallId,
    requested_date: args.requested_date || '',
    service_type: args.service_type || 'general',
    duration_minutes: Number(args.duration_minutes) || 60,
  },
}];

const res = $input.first().json;
const slots = Array.isArray(res.slots) ? res.slots : [];
let result;
if (slots.length === 0) {
  result = "I couldn't find an opening in that window. Our next opening is usually within 2 business days — " +
    "let the caller know the team will call to confirm a time.";
} else {
  result = slots.map((s, i) => {
    const d = new Date(s.start);
    const day = d.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' });
    const time = d.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
    return `Option ${i + 1}: ${day} at ${time}`;
  }).join(', or ');
}
return [{ json: { tool_call_id: $('Parse Tool Call').first().json.tool_call_id, result } }];
